import {rengokuSprite} from './rengoku.js';
import {drawSukunaChat,sukunaSprite} from './sukuna.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
import {boaSprite,drawBoaShot} from './boa.js';
import {tatsuSprite} from './tatsumaki.js';
import {saberSprite,drawSaberShot} from './saber.js';
import {ultraSprite,drawUltraShot} from './ultra.js';
import {BEERUS_NATIVE_META} from './beerus-meta.js';
import {jinwooSprite} from './jinwoo.js';
import {drawTeamDialogue} from './team-dialogue.js';
import {ichigoSprite,drawIchigoShot} from './ichigo.js';
import {drawProjectileEnergy} from './projectile-energy.js';
import {ULTIMATE_RULES,ULTIMATE_STYLES,ultimateCaster} from '../engine/team-ultimate.js';
function sprite(ctx,images,row,col,x,y,w,h,angle=0,flip=false){const im=images.team_ultimate;if(!im?.complete||!im.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.rotate(angle);if(flip)ctx.scale(-1,1);ctx.drawImage(im,col*1024,row*512,1024,512,-w/2,-h/2,w,h);ctx.restore();}
function circle(ctx,x,y,r,color,width=2){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
const PORTRAIT_RECTS={goku:[82,42,112,112],goku_blue:[105,40,110,115],vegeta:[108,40,106,112],broly:[106,48,118,115],piccolo:[100,50,110,112],naruto:[109,47,94,110],gojo:[112,45,103,111],sasuke:[116,43,96,110],gogeta:[116,40,108,115],luffy:[110,48,110,114],frieza:[116,48,88,110],gaara:[105,44,100,112],yugi:[110,45,105,114],beerus:[115,30,95,125]};
function portrait(ctx,images,f,x,y,size){const im=images[f.id];ctx.save();ctx.beginPath();ctx.arc(x,y,size/2,0,Math.PI*2);ctx.clip();ctx.fillStyle='#10101b';ctx.fillRect(x-size/2,y-size/2,size,size);if(f.id==='beerus'&&im?.complete&&im.naturalWidth)ctx.drawImage(im,...BEERUS_NATIVE_META.beerus.portraitRect,x-size/2,y-size/2,size,size);else if(f.id==='rengoku')rengokuSprite(ctx,images,'rengoku',0,0,x,y+size*.4,size/180);else if(f.id==='boa_hancock')boaSprite(ctx,images,'boa_hancock_dialogue',2,0,x,y,size/650);else if(f.id==='tatsumaki')tatsuSprite(ctx,images,'tatsumaki_dialogue',2,0,x,y,size/650);else if(f.id==='saber')saberSprite(ctx,images,'saber_dialogue',2,0,x,y,size/650);else if(f.id==='goku_ultra')ultraSprite(ctx,images,'goku_ultra_dialogue',2,0,x,y,size/750);else if(f.id==='sung_jinwoo')jinwooSprite(ctx,images,'sung_jinwoo_dialogue',2,0,x,y,size/450);else if(f.id==='ichigo')ichigoSprite(ctx,images,'ichigo_dialogue',2,0,x,y,size/500);else if(im?.complete&&im.naturalWidth)ctx.drawImage(im,...(PORTRAIT_RECTS[f.id]||[100,40,115,115]),x-size/2,y-size/2,size,size);ctx.restore();circle(ctx,x,y,size/2,ULTIMATE_STYLES[f.id].color,2);}
export function teamUltimatePose(d,f){const a=ultimateCaster(d,f);if(!a)return null;const count=f.id==='ichigo'?4:['gogeta','frieza'].includes(f.id)?8:6,p=d.teamUltimate.cinematic?d.teamUltimate.cinematic.elapsed/cinematicSteps(d.teamUltimate.cinematic):(d.tick-a.born)/36;return {row:a.style.cast,frame:Math.min(count-1,Math.floor(p*count))};}
export function drawTeamUltimateWorld(ctx,images,d,clock,reduced=false){
 const u=d.teamUltimate;if(!u)return;const c=u.cinematic,a=u.attack;
 if(c){const leader=d.fighters.find(f=>f.uid===c.leaderUid);for(const uid of c.members){const f=d.fighters.find(f=>f.uid===uid);if(!f||f===leader)continue;const p=(c.elapsed/cinematicSteps(c)+.2*c.members.indexOf(uid))%1,color=ULTIMATE_STYLES[f.id].color;ctx.save();ctx.globalAlpha=.75;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(f.x,f.y-40);ctx.quadraticCurveTo((f.x+leader.x)/2,Math.min(f.y,leader.y)-135,leader.x,leader.y-65);ctx.stroke();const x=f.x+(leader.x-f.x)*p,y=f.y+(leader.y-f.y)*p-40-Math.sin(p*Math.PI)*70;circle(ctx,x,y,6,color,4);ctx.restore();}sprite(ctx,images,0,Math.min(3,Math.floor(c.elapsed/cinematicSteps(c)*4)),leader.x,leader.y-65,300,150);}
 if(!a)return;const color=a.style.color,progress=Math.max(0,Math.min(1,(d.tick-a.launch)/ULTIMATE_RULES.travelTicks));
 if(a.phase==='warning'){
  ctx.save();ctx.setLineDash([10,7]);circle(ctx,a.targetX,a.targetY,ULTIMATE_RULES.radius,color,3);ctx.setLineDash([]);circle(ctx,a.targetX,a.targetY,ULTIMATE_RULES.radius*Math.max(.05,(d.tick-a.born)/36),color,2);ctx.font='bold 13px Segoe UI';ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText('ULTIMATE / TEAM '+a.team,a.targetX,a.targetY-ULTIMATE_RULES.radius-12);sprite(ctx,images,0,2,a.x,a.y-70,290,145);ctx.restore();return;
 }
 if(a.phase==='travel'){
  const x=a.x+(a.targetX-a.x)*progress,y=a.y+(a.targetY-a.y)*progress-45,dx=x-a.x,dy=y-(a.y-45),angle=Math.atan2(dy,dx);
  const energy={id:d.fighters.find(f=>f.uid===a.leaderUid)?.id,ownerUid:a.leaderUid,kind:'ultimate',vx:a.targetX-a.x,vy:a.targetY-a.y},profile={shape:a.style.row<=2?'beam':a.style.row===4?'wind':'orb',color:a.style.color,accent:a.style.row===3?'#edc8ff':'#f1fcff',radius:a.style.row<=2?42:55,length:a.style.row<=2?Math.hypot(dx,dy)+80:170,lightning:reduced?1:4,dark:a.style.row===3};drawProjectileEnergy(ctx,energy,{x,y},clock,{layer:'back',reduced,profile});
  if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='rengoku')rengokuSprite(ctx,images,'rengoku_ultimate_vfx',0,Math.min(5,Math.floor(progress*6)),x,y,.95,angle);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='sukuna')sukunaSprite(ctx,images,'sukuna_vfx',0,3,x,y,.9,angle);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='boa_hancock')drawBoaShot(ctx,images,{kind:'judgmentarrow',skill:'judgment',vx:a.targetX-a.x,vy:a.targetY-a.y},x,y,clock);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='tatsumaki')tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',1,Math.min(5,Math.floor(progress*6)),x,y,1.1,angle-Math.PI/4);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='saber')drawSaberShot(ctx,images,{kind:'excalibur',vx:a.targetX-a.x,vy:a.targetY-a.y},x,y,clock);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='goku_ultra')drawUltraShot(ctx,images,{kind:'supreme',vx:a.targetX-a.x,vy:a.targetY-a.y},x,y,clock);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='sung_jinwoo')jinwooSprite(ctx,images,'sung_jinwoo_ultimate_vfx',2,Math.min(5,Math.floor(progress*6)),x,y,.95,0,a.targetX<a.x?-1:1);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='ichigo')drawIchigoShot(ctx,images,{id:'ichigo',ownerUid:a.leaderUid,kind:'fullgetsuga',vx:a.targetX-a.x,vy:a.targetY-a.y},x,y,clock,reduced);else if(a.style.row<=2)sprite(ctx,images,a.style.row,2,(a.x+x)/2,(a.y-45+y)/2,Math.max(190,Math.hypot(dx,dy)+150),235,angle);
  else sprite(ctx,images,a.style.row,2,x,y,430,235,angle+(a.style.row===4?clock*8:0),a.style.row===3);
  drawProjectileEnergy(ctx,energy,{x,y},clock,{layer:'front',reduced,profile});
 }else{
  const p=(d.tick-a.impact)/48,scale=reduced?1:1+Math.sin(p*Math.PI)*.2;
  ctx.save();ctx.globalAlpha=Math.max(0,1-Math.max(0,p-.45)/.55);if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='rengoku')rengokuSprite(ctx,images,'rengoku_ultimate_vfx',1,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY,1.2*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='sukuna')sukunaSprite(ctx,images,'sukuna_ultimate_vfx',2,Math.min(3,Math.floor(p*4)),a.targetX,a.targetY,1.5*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='boa_hancock')boaSprite(ctx,images,'boa_hancock_ultimate_vfx',3,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY-25,1.3*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='boa_hancock')drawBoaShot(ctx,images,{kind:'judgmentarrow',skill:'judgment',vx:a.targetX-a.x,vy:a.targetY-a.y},x,y,clock);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='tatsumaki')tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',3,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY-25,1.55*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='saber')saberSprite(ctx,images,'saber_ultimate_vfx',3,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY-45,1.4*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='goku_ultra')ultraSprite(ctx,images,'goku_ultra_ultimate_vfx',3,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY-45,1.3*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='sung_jinwoo')jinwooSprite(ctx,images,'sung_jinwoo_ultimate_vfx',3,Math.min(5,Math.floor(p*6)),a.targetX,a.targetY-45,1.1*scale);else if(d.fighters.find(f=>f.uid===a.leaderUid)?.id==='ichigo')ichigoSprite(ctx,images,'ichigo_ultimate_vfx',1,Math.min(3,Math.floor(p*4)),a.targetX,a.targetY-45,.9*scale);else sprite(ctx,images,a.style.row,3,a.targetX,a.targetY-45,620*scale,350*scale);circle(ctx,a.targetX,a.targetY,40+p*ULTIMATE_RULES.radius*1.2,color,Math.max(1,5*(1-p)));ctx.restore();
 }
}
export function drawTeamUltimateCinematic(ctx,images,d,names,reduced=false){const c=d.teamUltimate?.cinematic;if(c&&d.fighters.find(f=>f.uid===c.leaderUid)?.id==='sukuna'){drawSukunaChat(ctx,images,c);return;}drawTeamDialogue(ctx,images,d,names,portrait,reduced);}
